  KEY `idx_settlement_date` (`settlement_id`,`date_time`) USING BTREE,
  KEY `idx_store_date` (`store`,`date_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='亚马逊支付报告表';

