  `subject_id` bigint unsigned DEFAULT NULL COMMENT '会计科目ID',
  `period` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '会计期间，格式：YYYYMM',
