  `attachment_type` varchar(20) COLLATE utf8mb4_bin DEFAULT 'IMAGE' COMMENT '附件类型：IMAGE（影像件）/PDF（电子票）/XML（数电XML）/OTHER（其他）',
  `upload_by` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '上传人（操作员账号）',
